def reverse_pairs(nums):
    def sort(low, high):
        if low >= high:
            return 0
        mid = (low + high) // 2
        count = sort(low, mid) + sort(mid + 1, high)
        right = mid + 1
        for left in range(low, mid + 1):
            while right <= high and nums[left] > 2 * nums[right]:
                right += 1
            count += right - (mid + 1)
        nums[low:high + 1] = sorted(nums[low:high + 1])
        return count

    return sort(0, len(nums) - 1)
